-- =====================================================================================
--  SEED 92 — KHÔI PHỤC DỮ LIỆU MẪU TẤT TOÁN sau khi chạy test ASC-006/009/010/011 (26/11/2026)
-- =====================================================================================
--  Test đã: từ chối yêu cầu hoàn tiền mẫu JGSAMPLERF02, từ chối đợt nháp #2, tạo đợt #3 (từ chối) và
--  #4 (đã DUYỆT -> cộng ví đối tác 2 và 3). Script này đưa các bảng về đúng snapshot trước test:
--  settlements, settlement_details, provider_revenues, wallets, refund_requests #2; xoá đợt #3/#4,
--  giao dịch ví, nhật ký hoàn tiền, thông báo phát sinh sau snapshot.
--
--  Chạy THỬ (ROLLBACK):  psql -h localhost -U postgres -d journeygo_db -v DRY_RUN=1 -f 92_restore_settlement_sample.sql
--  Chạy THẬT:            psql -h localhost -U postgres -d journeygo_db -f 92_restore_settlement_sample.sql
--  Nên chạy script này TRƯỚC 91_cleanup_api_test_data.sql. Luôn BACKUP trước.
-- =====================================================================================
\set ON_ERROR_STOP on
BEGIN;

-- 1) gỡ các bản ghi sinh ra sau snapshot TRƯỚC (đợt #3/#4 giữ khoá duy nhất theo kỳ nên phải xoá trước khi khôi phục đợt #2)
DELETE FROM wallet_transactions WHERE id > 2;
UPDATE provider_revenues SET settlement_id = NULL WHERE settlement_id > 2;
DELETE FROM settlement_details WHERE id > 7;
DELETE FROM settlements WHERE id > 2;

-- 2) khôi phục các dòng về đúng giá trị snapshot
